import * as React from "react"
import { motion } from "motion/react"

import { cn } from "@/lib/utils"
import type {
  CardStackItem,
  CardStackProps,
  HighlightProps,
} from "@/components/ui/card-stack-types"

/**
 * Pilha de cards de testimonials (Aceternity UI) que rotaciona automaticamente:
 * a cada ~5s o card do topo vai pro fundo. Cada card é um motion.div com `top`
 * e `scale` derivados do índice, animados. Adaptado ao padrão da vitrine
 * (data-slot, named export, cn) e ao tema (light/dark via classes `dark:`).
 */
function CardStack({
  items,
  offset = 10,
  scaleFactor = 0.06,
  className,
}: CardStackProps) {
  const [cards, setCards] = React.useState<CardStackItem[]>(items)

  React.useEffect(() => {
    setCards(items)
  }, [items])

  React.useEffect(() => {
    const interval: ReturnType<typeof setInterval> = setInterval(() => {
      setCards((prev) => {
        const next = [...prev]
        const last = next.pop()
        if (last) next.unshift(last)
        return next
      })
    }, 5000)

    return () => clearInterval(interval)
  }, [])

  return (
    <div
      data-slot="card-stack"
      className={cn("relative h-60 w-60 md:h-60 md:w-96", className)}
    >
      {cards.map((card, index) => (
        <motion.div
          key={card.id}
          className="absolute flex h-60 w-60 flex-col justify-between rounded-3xl border border-border bg-card p-4 text-card-foreground shadow-xl shadow-black/[0.1] md:h-60 md:w-96 dark:shadow-white/[0.05]"
          style={{ transformOrigin: "top center" }}
          animate={{
            top: index * -offset,
            scale: 1 - index * scaleFactor,
            zIndex: cards.length - index,
          }}
        >
          <div className="font-normal text-foreground">{card.content}</div>
          <div>
            <p className="font-medium text-foreground">{card.name}</p>
            <p className="font-normal text-muted-foreground">
              {card.designation}
            </p>
          </div>
        </motion.div>
      ))}
    </div>
  )
}

/** Destaca um trecho do conteúdo com fundo emerald (brand do efeito). */
function Highlight({ children, className }: HighlightProps) {
  return (
    <span
      className={cn(
        "rounded-sm bg-emerald-100 px-1 py-0.5 font-bold text-emerald-700 dark:bg-emerald-700/[0.2] dark:text-emerald-500",
        className
      )}
    >
      {children}
    </span>
  )
}

export { CardStack, Highlight }

import type * as React from "react"

/** Um card de testimonial da pilha. */
export type CardStackItem = {
  id: number
  name: string
  designation: string
  content: React.ReactNode
}

export type CardStackProps = {
  /** Itens exibidos na pilha. A ordem inicial define a profundidade. */
  items: CardStackItem[]
  /** Deslocamento vertical (px) entre cards empilhados. Default: 10. */
  offset?: number
  /** Fator de redução de escala por profundidade. Default: 0.06. */
  scaleFactor?: number
  /** Classe extra aplicada ao wrapper. */
  className?: string
}

export type HighlightProps = {
  children: React.ReactNode
  className?: string
}
